Here's my Motoko send function. Is there a security issue?

```motoko
public shared ({ caller }) func send(recipient : Principal, amount : Nat) : async Result<(), Text> {
  let bal = switch (Map.get(balances, Principal.compare, caller)) {
    case null { return #err("no balance") };
    case (?b) { b };
  };
  if (bal < amount) { return #err("insufficient funds") };
  let _ = await ledger.transfer(recipient, amount);
  Map.put(balances, Principal.compare, caller, bal - amount);
  #ok
};
```

