My Motoko canister stores user profiles in a HashMap and serializes them during upgrades. Is there a risk with this pattern as the user base grows?

```motoko
actor {
  var profiles : HashMap.HashMap<Principal, Profile> = HashMap.HashMap(0, Principal.equal, Principal.hash);
  stable var profilesStable : [(Principal, Profile)] = [];

  system func preupgrade() {
    profilesStable := Iter.toArray(profiles.entries());
  };

  system func postupgrade() {
    profiles := HashMap.fromIter(profilesStable.vals(), 0, Principal.equal, Principal.hash);
    profilesStable := [];
  };
};
```
